WITH base AS (SELECT id, supplier_name, country, city, rating, ROUND(rating, 2) AS rating_rounded, COALESCE(city, 'UNKNOWN') AS city_clean FROM suppliers WHERE country IN ('DE', 'TH', 'US')) SELECT id, supplier_name, city, city_clean, FIRST_VALUE(rating, TRUE) OVER (PARTITION BY city ORDER BY rating_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_rating, AVG(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS rating_avg_3, NTILE(10) OVER (ORDER BY rating_rounded, id) AS rating_rounded_bucket, SUM(rating_rounded) OVER (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_rating_rounded, SUM(rating_rounded) OVER (PARTITION BY city ORDER BY rating_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_rating_rounded FROM base
